using Microsoft.AspNetCore.Mvc; using System.Text.Json; using RaceDay.MvC.Models; using RaceDay.MvC.Services;
namespace RaceDay.MvC.Controllers;
public class OrganiserController(RaceDayApiClient api):Controller { private IActionResult? Guard(){if(HttpContext.Session.GetInt32("UserID")==null)return RedirectToAction("Login","Account");if(HttpContext.Session.GetString("Role")!="Organiser")return Forbid();return null;} public async Task<IActionResult> Index(){var g=Guard();if(g!=null)return g;var r=await api.Get<List<EventViewModel>>("api/events");var mine=(r.Data??new()).Where(x=>x.OrganiserID==HttpContext.Session.GetInt32("UserID")).ToList();foreach(var e in mine){var enrolments=await api.Get<List<EnrolmentViewModel>>($"api/events/{e.EventID}/enrolments");e.TotalEnrolments=enrolments.Data?.Count??0;}ViewBag.Error=r.Error;return View(mine);} public IActionResult Create(){var g=Guard();if(g!=null)return g;return View(new EventViewModel());} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(EventViewModel m){var g=Guard();if(g!=null)return g;if(!ModelState.IsValid)return View(m);var body=new{m.EventName,m.Description,m.EventDate,m.StartTime,m.Location,m.Distance,m.EventType,m.StartLocation,m.FinishLocation};var r=await api.Send<JsonElement>(HttpMethod.Post,"api/events",body);if(!r.Ok){ModelState.AddModelError("",r.Error??"Could not create event.");return View(m);}TempData["Success"]="Event created.";return RedirectToAction(nameof(Index));} public async Task<IActionResult> Edit(int id){var g=Guard();if(g!=null)return g;var r=await api.Get<EventViewModel>($"api/events/{id}");if(!r.Ok||r.Data!.OrganiserID!=HttpContext.Session.GetInt32("UserID"))return NotFound();return View(r.Data);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,EventViewModel m){var g=Guard();if(g!=null)return g;if(!ModelState.IsValid)return View(m);var r=await api.Send<JsonElement>(HttpMethod.Put,$"api/events/{id}",m);if(!r.Ok){ModelState.AddModelError("",r.Error??"Could not update event.");return View(m);}TempData["Success"]="Event updated.";return RedirectToAction(nameof(Index));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){var g=Guard();if(g!=null)return g;var r=await api.SendNoData(HttpMethod.Delete,$"api/events/{id}");TempData[r.Ok?"Success":"Error"]=r.Error??"Event deleted.";return RedirectToAction(nameof(Index));} public async Task<IActionResult> Enrolments(int id){var g=Guard();if(g!=null)return g;var r=await api.Get<List<EnrolmentViewModel>>($"api/events/{id}/enrolments");ViewBag.Error=r.Error;ViewBag.EventId=id;return View(r.Data??new());} public IActionResult Categories()=>RedirectToAction("Index","Events"); public async Task<IActionResult> Results(int id){var g=Guard();if(g!=null)return g;var r=await api.Get<List<EnrolmentViewModel>>($"api/events/{id}/enrolments");ViewBag.Error=r.Error;ViewBag.EventId=id;return View(r.Data??new());} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> AddResult(int id,int enrolmentId,string? finishTime,int? position,int? categoryPosition,decimal? pace){var g=Guard();if(g!=null)return g;TimeSpan? finish=TimeSpan.TryParse(finishTime,out var t)?t:null;var r=await api.Send<JsonElement>(HttpMethod.Post,"api/results",new{EnrolmentID=enrolmentId,FinishTime=finish,Position=position,CategoryPosition=categoryPosition,Pace=pace,ResultStatus="Published"});TempData[r.Ok?"Success":"Error"]=r.Error??(r.Ok?"Result saved.":"Could not save result.");return RedirectToAction(nameof(Results),new{id});} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> UploadBanner(int id, IFormFile file){var g=Guard();if(g!=null)return g;if(file is null){TempData["Error"]="Select an image first.";return RedirectToAction(nameof(Edit),new{id});}var r=await api.SendFile<JsonElement>($"api/events/{id}/banner",file);TempData[r.Ok?"Success":"Error"]=r.Error??(r.Ok?"Banner uploaded.":"Could not upload banner.");return RedirectToAction(nameof(Edit),new{id});} public async Task<IActionResult> Banner(int id){var r=await api.GetFile($"api/events/{id}/banner");return r.Ok&&r.Data is not null?File(r.Data,r.ContentType??"image/jpeg"):NotFound();} }